"""Parser for translation files generated by ``renpy translate``.

Two block shapes are understood::

    # game/script.rpy:14
    translate vietnamese start_a1b2c3d4:

        # e "Hello"
        e "Hello"

    translate vietnamese strings:

        # game/screens.rpy:20
        old "Start"
        new "Start"

Everything else (python/style blocks, comments, unrelated statements) is left untouched.
"""

from __future__ import annotations

import enum
import hashlib
import re
from collections.abc import Sequence
from dataclasses import dataclass, field
from pathlib import PurePosixPath

from renslate.core.models import UnitKind
from renslate.renpy.literals import decode_say_text, parse_python_string

_WORD = r"(?:[A-Za-z_][\w.]*|@|-[A-Za-z_]\w*)"
_QUOTED_SPEAKER = r'"(?:[^"\\]|\\.)*"'
_PREFIX = rf"(?:(?:{_WORD}\s+)+|{_QUOTED_SPEAKER}\s+)"
_SAY = re.compile(rf'(?P<prefix>{_PREFIX}?)"(?P<body>(?:[^"\\]|\\.)*)"(?P<suffix>.*)')
_UNSUPPORTED_SAY = re.compile(rf"""(?:{_WORD}\s+)*(?:"{{3}}|[rR]?['`]|[rR]")""")
_HEADER = re.compile(r"translate\s+(?P<language>\w+)\s+(?P<ident>\w+)(?P<rest>.*)")
_HEADER_TAIL = re.compile(r"\s*:\s*(?:#.*)?")
_REFERENCE = re.compile(r"#\s*(?!TODO\b)(?P<ref>\S.*:\d+)\s*")
_STRING_LINE = re.compile(r"(?P<head>\s+(?P<keyword>old|new)\s+)(?P<literal>.+)")
_IDENT_LABEL = re.compile(r"(?P<label>.+)_[0-9a-f]{8}(?:_\d+)?")

_NON_SAY_KEYWORDS = frozenset(
    {
        "as",
        "assert",
        "break",
        "call",
        "camera",
        "class",
        "config",
        "continue",
        "def",
        "default",
        "define",
        "del",
        "elif",
        "else",
        "except",
        "finally",
        "for",
        "from",
        "global",
        "gui",
        "hide",
        "if",
        "image",
        "import",
        "in",
        "init",
        "is",
        "jump",
        "label",
        "lambda",
        "layeredimage",
        "menu",
        "nvl",
        "pass",
        "pause",
        "persistent",
        "play",
        "python",
        "queue",
        "raise",
        "renpy",
        "return",
        "scene",
        "screen",
        "show",
        "stop",
        "store",
        "style",
        "transform",
        "translate",
        "try",
        "voice",
        "while",
        "window",
        "with",
        "yield",
    }
)
_UI_FILE_NAMES = frozenset(
    {"screens.rpy", "gui.rpy", "options.rpy", "common.rpy", "ui_strings.rpy"}
)


class Severity(str, enum.Enum):
    ERROR = "error"
    WARNING = "warning"


@dataclass(frozen=True, slots=True)
class Issue:
    severity: Severity
    code: str
    file: str
    line: int
    message: str


@dataclass(frozen=True, slots=True)
class SayStatement:
    """A say statement split around its string: ``prefix "text" suffix``."""

    prefix: str
    text: str
    suffix: str

    @property
    def speaker(self) -> str | None:
        stripped = self.prefix.strip()
        if stripped.startswith('"') and stripped.endswith('"') and len(stripped) >= 2:
            return decode_say_text(stripped[1:-1])
        words = self.prefix.split()
        if not words or words[0] == "extend" or words[0][0] in "@-":
            return None
        return words[0]


@dataclass(frozen=True, slots=True)
class ParsedUnit:
    uid: str
    kind: UnitKind
    source: str
    existing: str | None
    ref: str | None
    speaker: str | None
    label: str | None
    file: str
    line: int
    anchor_line: int
    fingerprint: str


def fingerprint(anchor: str, line: str) -> str:
    """Digest binding a slot's anchor line to its target line."""
    digest = hashlib.sha1(f"{anchor}\0{line}".encode(), usedforsecurity=False)
    return digest.hexdigest()


def string_uid(source: str) -> str:
    digest = hashlib.sha1(source.encode(), usedforsecurity=False)
    return f"s:{digest.hexdigest()[:20]}"


def _first_word(prefix: str) -> str | None:
    words = prefix.split()
    return words[0] if words else None


def parse_say(code: str) -> SayStatement | None:
    """Parse a stripped statement as a double-quoted say statement, or return None."""
    match = _SAY.match(code)
    if match is None or code.startswith('"""', match.end("prefix")):
        return None
    prefix = match.group("prefix")
    if _first_word(prefix) in _NON_SAY_KEYWORDS:
        return None
    return SayStatement(prefix, decode_say_text(match.group("body")), match.group("suffix"))


def _is_unsupported_say(code: str) -> bool:
    match = _UNSUPPORTED_SAY.match(code)
    return match is not None and _first_word(code[: match.end()]) not in _NON_SAY_KEYWORDS


def parse_string_line(line: str, keyword: str) -> tuple[str, str] | None:
    """Parse an ``old``/``new`` line into its head (indent and keyword) and string value."""
    match = _STRING_LINE.fullmatch(line)
    if match is None or match.group("keyword") != keyword:
        return None
    value = parse_python_string(match.group("literal"))
    return (match.group("head"), value) if value is not None else None


def _comment_code(stripped: str) -> str:
    return stripped[1:].lstrip()


def _is_ui(ref: str | None, file: str) -> bool:
    if PurePosixPath(file).name in _UI_FILE_NAMES:
        return True
    if ref is None:
        return False
    path = ref.rsplit(":", 1)[0]
    return PurePosixPath(path).name in _UI_FILE_NAMES or path.startswith(("renpy/", "common/"))


def _differs(existing: str, source: str) -> str | None:
    return existing if existing and existing != source else None


@dataclass(slots=True)
class TranslationScanner:
    """Collects translatable units and parse issues from translation files of one language."""

    language: str
    units: list[ParsedUnit] = field(default_factory=list)
    issues: list[Issue] = field(default_factory=list)
    _dialogue_ids: dict[str, str] = field(default_factory=dict)

    def _issue(self, severity: Severity, code: str, file: str, line: int, message: str) -> None:
        self.issues.append(Issue(severity, code, file, line, message))

    def scan_file(self, file: str, lines: Sequence[str]) -> None:
        reference: str | None = None
        index = 0
        while index < len(lines):
            line = lines[index]
            index += 1
            if not line.strip() or line[0] in " \t":
                continue
            if (ref_match := _REFERENCE.fullmatch(line)) is not None:
                reference = ref_match.group("ref")
                continue
            header = _HEADER.fullmatch(line.rstrip())
            if header is None:
                reference = None
                continue
            start = index
            while index < len(lines) and (not lines[index].strip() or lines[index][0] in " \t"):
                index += 1
            self._scan_block(file, lines, start - 1, index, header, reference)
            reference = None

    def _scan_block(
        self,
        file: str,
        lines: Sequence[str],
        header_index: int,
        end: int,
        header: re.Match[str],
        reference: str | None,
    ) -> None:
        ident = header.group("ident")
        if header.group("language") != self.language:
            self._issue(
                Severity.WARNING,
                "foreign_language",
                file,
                header_index + 1,
                f"bỏ qua khối của ngôn ngữ '{header.group('language')}'",
            )
        elif ident == "strings":
            self._scan_strings(file, lines, header_index + 1, end)
        elif ident in ("python", "style"):
            return
        elif _HEADER_TAIL.fullmatch(header.group("rest")) is None:
            self._issue(
                Severity.ERROR, "bad_header", file, header_index + 1, "dòng translate không hợp lệ"
            )
        else:
            self._scan_dialogue(file, lines, header_index, end, ident, reference)

    def _statements(
        self, file: str, lines: Sequence[str], start: int, end: int
    ) -> tuple[list[tuple[int, SayStatement]], list[tuple[int, SayStatement]]]:
        comments: list[tuple[int, SayStatement]] = []
        codes: list[tuple[int, SayStatement]] = []
        for index in range(start, end):
            stripped = lines[index].strip()
            if not stripped:
                continue
            is_comment = stripped.startswith("#")
            code = _comment_code(stripped) if is_comment else stripped
            say = parse_say(code)
            if say is not None:
                (comments if is_comment else codes).append((index, say))
            elif _is_unsupported_say(code):
                self._issue(
                    Severity.WARNING,
                    "unsupported_syntax",
                    file,
                    index + 1,
                    "cú pháp lời thoại chưa được hỗ trợ, giữ nguyên dòng",
                )
        return comments, codes

    def _scan_dialogue(
        self,
        file: str,
        lines: Sequence[str],
        header_index: int,
        end: int,
        ident: str,
        reference: str | None,
    ) -> None:
        location = f"{file}:{header_index + 1}"
        if ident in self._dialogue_ids:
            self._issue(
                Severity.WARNING,
                "duplicate_id",
                file,
                header_index + 1,
                f"khối trùng '{ident}' bị bỏ qua, đang dùng khối tại {self._dialogue_ids[ident]}",
            )
            return
        self._dialogue_ids[ident] = location

        comments, codes = self._statements(file, lines, header_index + 1, end)
        if len(comments) > len(codes):
            self._issue(
                Severity.ERROR,
                "block_mismatch",
                file,
                header_index + 1,
                f"{len(comments)} câu gốc nhưng chỉ có {len(codes)} câu dịch",
            )
            return
        if len(codes) > len(comments):
            self._issue(
                Severity.WARNING,
                "extra_statements",
                file,
                header_index + 1,
                f"{len(codes)} câu dịch cho {len(comments)} câu gốc, giữ nguyên các câu dư",
            )

        label_match = _IDENT_LABEL.fullmatch(ident)
        label = label_match.group("label") if label_match else None
        for number, ((_, original), (code_index, current)) in enumerate(
            zip(comments, codes, strict=False)
        ):
            self.units.append(
                ParsedUnit(
                    uid=f"d:{ident}" if number == 0 else f"d:{ident}#{number}",
                    kind=UnitKind.DIALOGUE,
                    source=original.text,
                    existing=_differs(current.text, original.text),
                    ref=reference,
                    speaker=original.speaker,
                    label=label,
                    file=file,
                    line=code_index + 1,
                    anchor_line=header_index + 1,
                    fingerprint=fingerprint(lines[header_index], lines[code_index]),
                )
            )

    def _scan_strings(self, file: str, lines: Sequence[str], start: int, end: int) -> None:
        reference: str | None = None
        old_value: str | None = None
        old_index = -1
        block_reference: str | None = None
        for index in range(start, end):
            line = lines[index]
            stripped = line.strip()
            if not stripped:
                continue
            if stripped.startswith("#"):
                if (ref_match := _REFERENCE.fullmatch(stripped)) is not None:
                    reference = ref_match.group("ref")
                continue
            old_line = parse_string_line(line, "old")
            new_line = parse_string_line(line, "new")
            if old_line is not None:
                if old_value is not None:
                    self._issue(
                        Severity.ERROR,
                        "missing_new",
                        file,
                        old_index + 1,
                        "dòng 'old' không có dòng 'new' theo sau",
                    )
                old_value, old_index, block_reference = old_line[1], index, reference
                reference = None
            elif new_line is not None and old_value is not None:
                self._add_string(
                    file, lines, old_index, index, old_value, new_line[1], block_reference
                )
                old_value = None
            else:
                self._issue(
                    Severity.ERROR,
                    "bad_string_line",
                    file,
                    index + 1,
                    "dòng không hợp lệ trong khối strings",
                )
                old_value = None
        if old_value is not None:
            self._issue(
                Severity.ERROR,
                "missing_new",
                file,
                old_index + 1,
                "dòng 'old' không có dòng 'new' theo sau",
            )

    def _add_string(
        self,
        file: str,
        lines: Sequence[str],
        old_index: int,
        new_index: int,
        source: str,
        current: str,
        reference: str | None,
    ) -> None:
        kind = UnitKind.UI if _is_ui(reference, file) else UnitKind.STRING
        self.units.append(
            ParsedUnit(
                uid=string_uid(source),
                kind=kind,
                source=source,
                existing=_differs(current, source),
                ref=reference,
                speaker=None,
                label=None,
                file=file,
                line=new_index + 1,
                anchor_line=old_index + 1,
                fingerprint=fingerprint(lines[old_index], lines[new_index]),
            )
        )
